"""导出内置页面识别目录；不加载环境、模型或数据库。"""

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "src"))

from forj_review_assistant.businesses.page_catalog import page_catalog  # noqa: E402


def main():
    catalog = json.dumps(page_catalog(), ensure_ascii=False, indent=2)
    target = ROOT / "apps/extension/src/platform/browser/catalog/bundled-page-catalog.ts"
    target.write_text(
        '// Generated by scripts/dev/export-page-catalog.py; do not edit.\n'
        'import type { PageCatalog } from "./page-catalog.ts";\n\n'
        f'export const bundledPageCatalog: PageCatalog = {catalog};\n', encoding="utf-8",
    )
    (ROOT / "apps/extension/tests/fixtures/page-catalog.json").write_text(catalog + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
